.feed-container {
  max-width: 600px;
  margin: 40px auto;
  padding: 24px;
  background: var(--bg);
  border-radius: 12px;
  box-shadow: var(--shadow);
  text-align: left;
}

.feed-header {
  margin-bottom: 32px;
  border-bottom: 2px solid var(--border);
  padding-bottom: 16px;
}

.feed-header h1 {
  font-size: 32px;
  margin: 0 0 8px 0;
  color: var(--text-h);
}

.subtitle {
  font-size: 16px;
  color: var(--text);
  margin: 0;
}

.feed-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.feed-item {
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  transition: transform 0.2s, box-shadow 0.2s;
}

.feed-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.feed-item-badge {
  display: inline-block;
  font-size: 12px;
  font-weight: bold;
  color: var(--accent);
  background: var(--accent-bg);
  padding: 4px 8px;
  border-radius: 4px;
  margin-bottom: 8px;
}

.feed-item-title {
  font-size: 18px;
  margin: 0 0 8px 0;
  color: var(--text-h);
}

.feed-item-desc {
  font-size: 14px;
  color: var(--text);
  margin: 0;
  line-height: 1.5;
}

.feed-actions {
  margin-top: 32px;
  display: flex;
  justify-content: center;
}

.load-more-btn {
  font-family: var(--sans);
  font-size: 16px;
  font-weight: 600;
  padding: 12px 24px;
  color: #fff;
  background-color: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, opacity 0.2s;
  box-shadow: 0 4px 6px rgba(170, 59, 255, 0.2);
}

.load-more-btn:hover:not(:disabled) {
  background-color: #931bf2;
}

.load-more-btn:disabled {
  background-color: var(--border);
  color: var(--text);
  cursor: not-allowed;
  box-shadow: none;
  opacity: 0.7;
}

.feed-status {
  text-align: center;
  margin-top: 16px;
  font-size: 14px;
  color: var(--text);
  height: 20px;
}

.loading, .error {
  text-align: center;
  padding: 40px;
  font-size: 18px;
  color: var(--text);
}

.error {
  color: #ef4444;
}

import { QueryClient, QueryClientProvider, useInfiniteQuery } from '@tanstack/react-query';
import './App.css';

// Create a client
const queryClient = new QueryClient();

interface FeedItem {
  id: number;
  title: string;
  description: string;
}

interface FeedResponse {
  items: FeedItem[];
  nextCursor: number | null;
}

// Mock API function
export const fetchFeed = async (cursor: number = 0): Promise<FeedResponse> => {
  // Simulate network latency
  await new Promise((resolve) => setTimeout(resolve, 600));

  const itemsPerPage = 5;
  const totalItems = 25; // 5 pages of data

  const items: FeedItem[] = [];
  const start = cursor * itemsPerPage;
  const end = Math.min(start + itemsPerPage, totalItems);

  for (let i = start; i < end; i++) {
    items.push({
      id: i + 1,
      title: `Feed Item #${i + 1}`,
      description: `This is the description for feed item #${i + 1}. It is loaded dynamically using TanStack Query infinite query.`,
    });
  }

  const nextCursor = end < totalItems ? cursor + 1 : null;

  return {
    items,
    nextCursor,
  };
};

function Feed() {
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetching,
    isFetchingNextPage,
    status,
    error,
  } = useInfiniteQuery({
    queryKey: ['feed'],
    queryFn: ({ pageParam }) => fetchFeed(pageParam),
    initialPageParam: 0,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
  });

  return (
    <div className="feed-container">
      <header className="feed-header">
        <h1>TanStack Query Infinite Feed</h1>
        <p className="subtitle">Demonstrating pagination and server state management</p>
      </header>

      {status === 'pending' ? (
        <div className="loading">Loading initial feed...</div>
      ) : status === 'error' ? (
        <div className="error">Error loading feed: {(error as Error).message}</div>
      ) : (
        <>
          <ul className="feed-list">
            {data?.pages.flatMap((page) => page.items).map((item) => (
              <li key={item.id} className="feed-item">
                <div className="feed-item-badge">Item {item.id}</div>
                <h3 className="feed-item-title">{item.title}</h3>
                <p className="feed-item-desc">{item.description}</p>
              </li>
            ))}
          </ul>

          <div className="feed-actions">
            <button
              onClick={() => fetchNextPage()}
              disabled={!hasNextPage || isFetchingNextPage}
              className="load-more-btn"
            >
              Load More
            </button>
          </div>

          <div className="feed-status">
            {isFetchingNextPage ? 'Loading more...' : isFetching ? 'Background updating...' : null}
          </div>
        </>
      )}
    </div>
  );
}

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <Feed />
    </QueryClientProvider>
  );
}
